<?php $pageTitle='My account | HEX CHEATS SHOP';$activePage='account';require __DIR__.'/_head.php'; ?>
<section class="hx-page-heading"><p class="hx-eyebrow">MY HEX</p><h1>Account</h1><p class="hx-muted">Manage your customer profile and quickly reach your wallet, payments, orders and keys.</p></section><section class="hx-panel" id="accountCard"><div class="hx-loading">Checking your account…</div></section>
<script>(()=>{const box=document.getElementById('accountCard'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let csrf='';async function load(){try{const r=await fetch('/api/store/session',{credentials:'same-origin'}),d=await r.json();if(!d.authenticated){location.href='/login';return}csrf=d.csrf_token||'';const a=d.account||{};box.innerHTML=`<div class="hx-account-top"><div class="hx-avatar">${esc((a.display_name||a.email||'H').slice(0,1).toUpperCase())}</div><div><b>${esc(a.display_name||'Shop customer')}</b><div class="hx-muted">${esc(a.email||'')}</div></div></div><form id="profileForm" class="hx-form"><label>Display name<input name="display_name" maxlength="100" required value="${esc(a.display_name||'')}"></label><button class="hx-button" type="submit">Save profile</button><div id="profileStatus" class="hx-alert"></div></form><div class="hx-shortcuts"><a href="/wallet">Wallet &amp; payment history</a><a href="/orders">My orders</a><a href="/keys">Delivered keys</a></div><button class="hx-button hx-secondary" id="logout">Sign out</button>`;document.getElementById('profileForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,s=document.getElementById('profileStatus');try{const r=await fetch('/api/store/profile',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({display_name:f.display_name.value.trim()})}),x=await r.json();if(!r.ok)throw Error(x.error||'Could not save.');s.textContent='Profile saved.'}catch(x){s.textContent=x.message}};document.getElementById('logout').onclick=async()=>{await fetch('/api/store/logout',{method:'POST',credentials:'same-origin'});location.href='/'};}catch(e){box.textContent='Could not load your account. Please refresh.'}}load()})();</script>
